import math

def get_wall_by_guid(guid):
    for wall in ifc.by_type('IfcWall'):
        if wall.GlobalId == guid:
            return wall
    return None

def get_wall_center_and_bounds(wall):
    origin = ifcopenshell.util.placement.get_local_placement(wall.ObjectPlacement)
    # Default wall size
    length = 3000
    height = 2100
    # Try to infer from geometry where possible
    try:
        reps = wall.Representation.Representations
        for rep in reps:
            if rep.RepresentationType == 'SweptSolid':
                item = rep.Items[0]
                profile = getattr(item, 'SweptArea', None)
                if profile and hasattr(profile, 'ProfileType'):
                    # Use parameter if available
                    if hasattr(profile, 'XDim') and hasattr(profile, 'YDim'):
                        length = profile.XDim
                        height = profile.YDim
    except Exception:
        pass
    return origin, (length, height)

def find_wall_north_of_wall(base_wall):
    base_loc = ifcopenshell.util.placement.get_local_placement(base_wall.ObjectPlacement)
    base_x, base_y, base_z = [float(v) for v in base_loc]
    candidates = []
    for wall in ifc.by_type('IfcWall'):
        if wall == base_wall:
            continue
        loc = ifcopenshell.util.placement.get_local_placement(wall.ObjectPlacement)
        x, y, z = [float(v) for v in loc]
        if y > base_y and abs(x - base_x) < 2500:
            candidates.append((wall, y - base_y))
    if not candidates:
        return None
    # Return closest north wall
    return sorted(candidates, key=lambda tup: tup[1])[0][0]

