    try:
        values = list(loc) if hasattr(loc, '__iter__') else [loc]
        # Flatten further if elements are themselves iterable/array-like
        flat = []
        for v in values:
            if hasattr(v, '__iter__') and not isinstance(v, str):
                flat.extend(list(v))
            else:
                flat.append(v)
        xyz = [float(flat[i]) for i in range(3)]
