def is_related_to_slab(column, slab):
    # Check if the column has any relationship with the slab (via containment, aggregate, connections, spatial, etc.)
    for rel in ifc.get_inverse(column):
        items = []
        # rel can be IfcRelAggregates, IfcRelContainedInSpatialStructure, IfcRelConnects, etc.
        # Check RelatedElements, RelatedObjects, RelatedStructuralComponents, etc.
        for attr in ['RelatedElements', 'RelatedObjects', 'RelatedStructuralComponents', 'RelatedBuildingElement', 'RelatingElement', 'RelatingStructure', 'RelatingBuildingElement']:
            if hasattr(rel, attr):
                obj = getattr(rel, attr)
                if isinstance(obj, list):
                    items = obj
                elif obj is not None:
                    items = [obj]
                for i in items:
                    if i == slab:
                        return True
    return False

