# As final resort, sum up bounding box areas (XY) of IfcSpace representations, ignoring overlaps and voids.
def get_space_footprint(space):
    try:
        for rep in getattr(space, 'Representation', []) or []:
            if rep.is_a('IfcProductDefinitionShape'):
                for item in rep.Representations:
                    # Only use 'Body' or 'FootPrint' if available
                    if hasattr(item, 'RepresentationType') and item.RepresentationType in ['SweptSolid', 'SurfaceModel', 'Brep', 'CSG', 'MappedRepresentation']:
                        for geom in getattr(item, 'Items', []):
                            # Look for IfcExtrudedAreaSolid (extrusion in Z)
                            if geom.is_a('IfcExtrudedAreaSolid'):
                                profile = geom.SweptArea
                                if profile.is_a('IfcRectangleProfileDef'):
                                    return profile.XDim * profile.YDim
                                elif profile.is_a('IfcArbitraryClosedProfileDef'):
                                    # Try to sum polygon area
                                    outer = profile.OuterCurve
                                    if outer and outer.is_a('IfcPolyline'):
                                        points = outer.Points
                                        x, y = zip(*[(pt.Coordinates[0], pt.Coordinates[1]) for pt in points])
                                        # Close polyline
                                        if len(points) > 2:
                                            area = 0.5 * abs(sum(x[i] * y[i+1] - x[i+1] * y[i] for i in range(-1, len(points)-1)))
                                            return area
        return 0.0
    except Exception:
        return 0.0

