                            p2 = points[(i+1)%len(points)].Coordinates
                            total_length += sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)
                        height = abs(item.Depth)
                        return total_length * height
                    elif hasattr(swept, 'ProfileType') and swept.ProfileType.lower() == 'area':
