# Find non-rectangular spaces, then calculate their net volumes (in cubic meters)
from collections import Counter
import math

def is_rectangular(space):
    # Check if a space footprint (outline) is rectangular by examining the number of segments and angles
    if not hasattr(space, "Representation") or not space.Representation:
        return False
    reps = space.Representation.Representations
    for r in reps:
        if hasattr(r, 'Items'):
            for item in r.Items:
                if hasattr(item, 'Outer') and hasattr(item.Outer, 'Points'):
                    points = item.Outer.Points
                elif hasattr(item, 'Points'):
                    points = item.Points
                else:
                    continue
                # Collect 2D points (assuming they are 3D but floor-plan aligned)
                pts = [(float(p.Coordinates[0]), float(p.Coordinates[1])) for p in points]
                # It's rectangular if it has 4 points and all angles are 90 degrees (within precision)
                if len(pts) == 4:
                    angles = []
                    for i in range(4):
                        p1, p2, p3 = pts[i-1], pts[i], pts[(i+1)%4]
                        v1 = (p2[0]-p1[0], p2[1]-p1[1])
                        v2 = (p3[0]-p2[0], p3[1]-p2[1])
                        # Dot product
                        dot = v1[0]*v2[0] + v1[1]*v2[1]
                        norm1 = math.sqrt(v1[0]**2 + v1[1]**2)
                        norm2 = math.sqrt(v2[0]**2 + v2[1]**2)
                        if norm1 == 0 or norm2 == 0:
                            return False
                        cos_theta = dot / (norm1 * norm2)
                        angle = round(math.acos(cos_theta), 5)
                        angles.append(angle)
                    # All angles should be close to 90deg (pi/2)
                    if all(abs(a - math.pi/2) < 1e-2 for a in angles):
                        return True
    return False

