                    elif attr == 'Depth':
                        zmin = min(zmin, 0)
                        zmax = max(zmax, v)
    if (xmax > xmin) and (ymax > ymin) and (zmax > zmin):
        return (xmax - xmin) * (ymax - ymin) * (zmax - zmin)
    return None

