import ifcopenshell.util.element

def get_doors_between_rooms(ifc, start_room_id, end_room_id):
    # Helper: build graph with rooms as nodes, doors as edges
    from collections import deque, defaultdict

    # Helper functions
    def room_doors(room):
        # Finds all doors bounding this room
        rels = [r for r in ifc.by_type('IfcRelSpaceBoundary') if r.RelatedSpace and r.RelatedSpace.GlobalId == room.GlobalId]
        door_ids = set()
        for rel in rels:
            el = rel.RelatedBuildingElement
            if el and el.is_a('IfcDoor'):
                door_ids.add(el.GlobalId)
        return door_ids

    def door_connected_rooms(door):
        # Finds all rooms this door is adjacent to
        rels = [r for r in ifc.by_type('IfcRelSpaceBoundary') if r.RelatedBuildingElement and r.RelatedBuildingElement.GlobalId == door.GlobalId]
        room_ids = set()
        for rel in rels:
            sp = rel.RelatedSpace
            if sp:
                room_ids.add(sp.GlobalId)
        return room_ids

    # Build connections: room -> doors; door -> rooms
    rooms = {r.GlobalId: r for r in ifc.by_type('IfcSpace')}
    doors = {d.GlobalId: d for d in ifc.by_type('IfcDoor')}
    # Room graph: node = GlobalId (IfcSpace), edge = door GID
    room_graph = defaultdict(list)  # room id -> list of (door id, neighbor room id)
    # Link rooms via doors
    for door in doors.values():
        connected_rooms = door_connected_rooms(door)
        if len(connected_rooms) >= 2:
            cr_list = list(connected_rooms)
            # join all pairs
            for i in range(len(cr_list)):
                for j in range(i+1, len(cr_list)):
                    a, b = cr_list[i], cr_list[j]
                    room_graph[a].append((door.GlobalId, b))
                    room_graph[b].append((door.GlobalId, a))

    # BFS for shortest path from start_room_id to end_room_id
    queue = deque([(start_room_id, [])])  # (current_room, doors_used)
    seen = {start_room_id}
    while queue:
        rid, path = queue.popleft()
        if rid == end_room_id:
            return path  # found! return list of door ids
        for (door_id, neighbor_id) in room_graph[rid]:
            if neighbor_id not in seen:
                seen.add(neighbor_id)
                queue.append((neighbor_id, path + [door_id]))
    return []

