def get_space_lightness(space):
    # Get all related IfcFinish/IfcCoverings (walls/floors/ceilings) and extract their material
    rels = ifc.get_inverse(space)
    material_lightness = []
    for rel in rels:
        # IfcRelCoversSpaces connects coverings
