                mats = []
                for assoc in ifc.get_inverse(covering):
                    if assoc.is_a('IfcRelAssociatesMaterial'):
                        material = assoc.RelatingMaterial
                        if material.is_a('IfcMaterialLayerSetUsage'):
                            for layer in material.ForLayerSet.MaterialLayers:
