                # If no association, fallback to IfcCovering.Name/Description
                if not mats:
                    mats.append(covering)
                for mat in mats:
                    material_lightness.append(get_material_lightness(mat))
    # If nothing found, fallback to space Name/Description
    if not material_lightness:
        material_lightness.append(get_material_lightness(space))
    # Return average
