def wall_height(wall):
    # Try to get wall's bounding box height via direct geometry (avoid ifcopenshell.geom)
    # Use Representation/Body/Depth or parametric info if available
    if hasattr(wall, 'OverallHeight') and wall.OverallHeight:
        return float(wall.OverallHeight)
    # Try geometry via Representation, fallback to default 3.0m if missing
    try:
        shape = wall.Representation
        if shape and hasattr(shape, 'Representations'):
            for rep in shape.Representations:
                if hasattr(rep, 'Items'):
                    for item in rep.Items:
                        if hasattr(item, 'Height') and item.Height:
                            return float(item.Height)
    except Exception:
        pass
    # Default heuristic height
    return 3.0

