# Helper: get each room's centroid using bounding box approximation
def get_centroid(room):
    if hasattr(room, 'BoundedBy'):
        try:
            points = []
            for rel in room.BoundedBy:
                if hasattr(rel, 'RelatedBuildingElement') and hasattr(rel.RelatedBuildingElement, 'Representation'):
                    reps = rel.RelatedBuildingElement.Representation
                    if reps:
                        for rep in reps.Representations:
                            if hasattr(rep, 'Items'):
                                for item in rep.Items:
                                    if hasattr(item, 'Coordinates'):
                                        points.extend(item.Coordinates)
            if points:
                xs, ys, zs = zip(*points)
                cx = sum(xs)/len(xs)
                cy = sum(ys)/len(ys)
                cz = sum(zs)/len(zs)
                return (cx, cy, cz)
        except Exception:
            pass
    # Fallback: use object placement if possible
    try:
        placement = room.ObjectPlacement
        if placement and hasattr(placement, 'RelativePlacement'):
            rel = placement.RelativePlacement
            if hasattr(rel, 'Location') and hasattr(rel.Location, 'Coordinates'):
                coords = rel.Location.Coordinates
                if len(coords) == 3:
                    return tuple(coords)
                if len(coords) == 2:
                    return (coords[0], coords[1], 0)
    except Exception:
        pass
    return None

# Collect centroids for all rooms
room_centroids = []
for room in rooms:
    centroid = get_centroid(room)
    if centroid:
        room_centroids.append((room, centroid))

# Compute centroid of all rooms as context center
if room_centroids:
    xs = [c[1][0] for c in room_centroids]
    ys = [c[1][1] for c in room_centroids]
    zs = [c[1][2] for c in room_centroids]
    context_cx = sum(xs)/len(xs)
    context_cy = sum(ys)/len(ys)
    context_cz = sum(zs)/len(zs)
    context_centroid = (context_cx, context_cy, context_cz)

    # Find the room whose centroid is closest to the context centroid
    def dist(a, b):
        return ((a[0]-b[0])**2 + (a[1]-b[1])**2 + (a[2]-b[2])**2)**0.5

    min_room, min_dist = None, float('inf')
    for room, centroid in room_centroids:
        d = dist(centroid, context_centroid)
        if d < min_dist:
            min_room, min_dist = room, d
    result = min_room.GlobalId
else:
    result = None

commit()

# Fix function to handle missing RefDirection or DirectionRatios gracefully.
def is_south_facing(wall):
    placement = wall.ObjectPlacement
