    rel_placement = placement.RelativePlacement
    ref_dir = getattr(rel_placement, 'RefDirection', None)
    if not (ref_dir and hasattr(ref_dir, 'DirectionRatios')):
        return False
    dir_vec = ref_dir.DirectionRatios
    if len(dir_vec) < 2:
        return False
    # South is -y, so y negative
    return dir_vec[1] < -0.5

