def get_wall_band_z(wall):
    placement = wall.ObjectPlacement
    if not hasattr(placement, 'RelativePlacement'):
        return None, None
    rel_placement = placement.RelativePlacement
    loc = getattr(rel_placement, 'Location', None)
    if not loc or not hasattr(loc, 'Coordinates'):
