# 1. Get all doors
# 2. Prefer a door in the lowest storey, preferably external, near an outer wall
# 3. If there is an IfcBuildingStorey with elevation = 0, use doors in that storey first
# 4. As fallback, just give the first door
doors = [e for e in ifc.by_type('IfcDoor')]
if not doors:
    result = None
else:
    # Get all storeys and their elevations
    storeys = {s.GlobalId: getattr(s, 'Elevation', 0) or 0 for s in ifc.by_type('IfcBuildingStorey')}
    # Map doors to their container storey, if possible
    door_to_storey = {}
    for door in doors:
        rels = [r for r in ifc.by_type('IfcRelContainedInSpatialStructure') if door in r.RelatedElements]
        for rel in rels:
            storey = rel.RelatingStructure
            door_to_storey[door.GlobalId] = storey
    # Find storey closest to ground, preferably elevation == 0
    ground_storey = None
    min_elev = float('inf')
    for sid, elev in storeys.items():
        if abs(elev) < abs(min_elev):
            min_elev = elev
            ground_storey = sid
    entry_candidates = []
    for door in doors:
        sgid = door_to_storey.get(door.GlobalId)
        if sgid == ground_storey:
            entry_candidates.append(door)
    if not entry_candidates:
        entry_candidates = doors
    # Prefer door with 'Entrance' in Name/ObjectType/Tag, or with external reference
    main_door = None
    for door in entry_candidates:
        n = str(getattr(door, 'Name', '') or '').lower()
        ot = str(getattr(door, 'ObjectType', '') or '').lower()
        tag = str(getattr(door, 'Tag', '') or '').lower()
        if 'entrance' in n or 'entrance' in ot or 'entrance' in tag:
            main_door = door
            break
    if not main_door:
        # Heuristic: pick the largest (width x height) door among the lowest storey
        max_area = -1
        for door in entry_candidates:
            try:
                for rdef in door.IsDefinedBy:
                    if rdef.is_a('IfcRelDefinesByProperties'):
                        props = rdef.RelatingPropertyDefinition
                        if props.is_a('IfcElementQuantity'):
                            for q in props.Quantities:
                                if q.is_a('IfcQuantityLength') and q.Name == 'Width':
                                    width = float(q.Value)
                                if q.is_a('IfcQuantityLength') and q.Name == 'Height':
                                    height = float(q.Value)
                            area = width * height if 'width' in locals() and 'height' in locals() else 0
                            if area > max_area:
                                max_area = area
                                main_door = door
            except Exception:
                continue
    if not main_door:
        # fallback
        main_door = entry_candidates[0]
    result = main_door.GlobalId
commit()
